#include "pbnfc.h"
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct { const char *s; size_t n,i; Location loc; MarkTokens *out; Error *err; } MLex;
static void adv(MLex *l){unsigned char c=(unsigned char)l->s[l->i++];l->loc.offset++;if(c=='\n'){l->loc.line++;l->loc.column=1;}else l->loc.column++;}
static bool add(MLex *l,int kind,const char *s,size_t n,Location loc){MarkToken *q;if(l->out->n==l->out->cap){size_t c=l->out->cap?l->out->cap*2:32;q=realloc(l->out->v,c*sizeof(*q));if(!q){error_set(l->err,loc,"out of memory");return false;}l->out->v=q;l->out->cap=c;}l->out->v[l->out->n].text=malloc(n+1);if(!l->out->v[l->out->n].text){error_set(l->err,loc,"out of memory");return false;}memcpy(l->out->v[l->out->n].text,s,n);l->out->v[l->out->n].text[n]=0;l->out->v[l->out->n].kind=kind;l->out->v[l->out->n++].loc=loc;return true;}
static bool ident0(unsigned char c){return isalpha(c)||c=='_'||c==':';}
static bool identc(unsigned char c){return isalnum(c)||c=='_'||c==':'||c=='.'||c=='-';}
static bool white(const char *s,size_t n){size_t i;for(i=0;i<n;i++)if(!(s[i]==' '||s[i]=='\t'||s[i]=='\r'||s[i]=='\n'||s[i]=='\f'||s[i]=='\v'))return false;return true;}
static bool read_file(const char *path,char **p,size_t *n,Error *e){FILE *f=fopen(path,"rb");long z;if(!f){error_set(e,(Location){0,1,1},"cannot open '%s'",path);return false;}if(fseek(f,0,SEEK_END)||(z=ftell(f))<0||fseek(f,0,SEEK_SET)){fclose(f);error_set(e,(Location){0,1,1},"cannot read '%s'",path);return false;}*p=malloc((size_t)z+1);if(!*p){fclose(f);error_set(e,(Location){0,1,1},"out of memory");return false;}if(fread(*p,1,(size_t)z,f)!=(size_t)z){fclose(f);free(*p);error_set(e,(Location){0,1,1},"cannot read '%s'",path);return false;}fclose(f);(*p)[z]=0;*n=(size_t)z;return true;}
void tokens_free(MarkTokens *t){size_t i;for(i=0;i<t->n;i++)free(t->v[i].text);free(t->v);memset(t,0,sizeof(*t));}
bool markup_load(const char *path,MarkTokens *out,Error *err){char *s;size_t n,b;bool tag=false,ok=true;MLex l;memset(out,0,sizeof(*out));if(!read_file(path,&s,&n,err))return false;l=(MLex){s,n,0,{0,1,1},out,err};while(l.i<n){Location here=l.loc;unsigned char c=(unsigned char)s[l.i];if(c==0||c<9||(c>13&&c<32)){error_set(err,here,"invalid byte in markup");ok=false;break;}if(!tag){if(c=='<'){if(!add(&l,MK_LITERAL,"<",1,here)){ok=false;break;}adv(&l);tag=true;continue;}b=l.i;while(l.i<n&&s[l.i]!='<'){if((unsigned char)s[l.i]==0){error_set(err,l.loc,"invalid byte in markup");ok=false;break;}adv(&l);}if(!ok)break;if(!white(s+b,l.i-b)&&!add(&l,MK_TEXT,s+b,l.i-b,here)){ok=false;break;}continue;}
if(isspace(c)){adv(&l);continue;}if(c=='>'||c=='/'||c=='='){char z=(char)c;if(!add(&l,MK_LITERAL,&z,1,here)){ok=false;break;}adv(&l);if(c=='>')tag=false;continue;}if(c=='\''||c=='"'){char quote=(char)c;size_t begin=l.i;adv(&l);while(l.i<n&&s[l.i]!=quote){if(s[l.i]=='\\'){adv(&l);if(l.i==n||(s[l.i]!=quote&&s[l.i]!='\\')){error_set(err,l.loc,"invalid escape in quoted value");ok=false;break;}}if(s[l.i]=='\n'||s[l.i]=='\r'){error_set(err,l.loc,"unterminated quoted value");ok=false;break;}adv(&l);}if(!ok)break;if(l.i==n){error_set(err,here,"unterminated quoted value");ok=false;break;}adv(&l);if(!add(&l,MK_STRING,s+begin,l.i-begin,here)){ok=false;break;}continue;}if(ident0(c)){b=l.i;while(l.i<n&&identc((unsigned char)s[l.i]))adv(&l);if(!add(&l,MK_IDENT,s+b,l.i-b,here)){ok=false;break;}continue;}error_set(err,here,"invalid character inside tag");ok=false;break;}
if(ok&&tag){error_set(err,l.loc,"unterminated tag");ok=false;}out->end=l.loc;free(s);if(!ok){tokens_free(out);return false;}return true;}
